export const pts=a=>a.map(p=>proj(p[0],p[1]).map(n=>n.toFixed(1)).join(',')).join(' ');
export const smooth=a=>{const P=a.map(p=>proj(p[0],p[1]));let d=`M${P[0][0].toFixed(1)},${P[0][1].toFixed(1)}`;for(let i=1;i<P.length;i++){const p0=P[i-1],p1=P[i];const mx=(p0[0]+p1[0])/2,my=(p0[1]+p1[1])/2;d+=` Q${p0[0].toFixed(1)},${p0[1].toFixed(1)} ${mx.toFixed(1)},${my.toFixed(1)}`;}const L=P[P.length-1];return d+` L${L[0].toFixed(1)},${L[1].toFixed(1)}`;};
export const hx=h=>[parseInt(h.slice(1,3),16),parseInt(h.slice(3,5),16),parseInt(h.slice(5,7),16)];
export const mix=(a,b,f)=>a.map((v,i)=>Math.round(v+(b[i]-v)*f));
export const rgb=(c,a)=>a==null?`rgb(${c[0]},${c[1]},${c[2]})`:`rgba(${c[0]},${c[1]},${c[2]},${a})`;
export function cairoMinutes(){try{const s=new Intl.DateTimeFormat('en-GB',{timeZone:'Africa/Cairo',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());const [h,mm]=s.split(':').map(Number);return h*60+mm;}catch(e){const d=new Date();return d.getUTCHours()*60+d.getUTCMinutes()+120;}}
export const fmtClock=m=>{m=((Math.round(m)%1440)+1440)%1440;return String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');};
