export function toGlyphs(name){const out=[];const s=name.toLowerCase().replace(/[^a-z]/g,'');for(let i=0;i<s.length;i++){const two=s.slice(i,i+2);if(HG[two]&&two.length===2){out.push([two,HG[two]]);i++;continue;}const c=HG[s[i]];if(c)out.push([s[i],c]);}return out.map(([l,c])=>[l,Array.isArray(c)?String.fromCodePoint(...c):String.fromCodePoint(c)]);}
export function countryOpts(sel){const all=[...Object.keys(VISA.free),...VISA.voa,...VISA.evisa,...VISA.embassy].sort();return all.map(c=>`<option ${c===(sel||'United Kingdom')?'selected':''}>${c}</option>`).join('');}
